import type { MarkLessonSlide } from './mark-6-lesson'

type Scene = Omit<MarkLessonSlide, 'connections' | 'recall'> & { connections?: MarkLessonSlide['connections']; recall?: string[] }
const scene = (value: Scene): MarkLessonSlide => ({ ...value, connections: value.connections ?? [{ label: 'Text note', references: value.passage, explanation: 'Read this scene in sequence and distinguish Mark’s stated details from later tradition or interpretation.' }], recall: value.recall ?? [`Retell ${value.passage} in your own words.`, 'Which detail would be easiest to miss on a quiz?'] })
const image = (chapter: number, name: string, alt: string) => ({ src: `/resources/mark/chapter-${chapter}/${name}.jpg`, alt: `Imagined historical reconstruction of ${alt}`, caption: 'Imagined historical reconstruction—not a photograph or a claim about the exact people, location, clothing, or architecture.' })
const review = (chapter: number, title: string, details: string[]): MarkLessonSlide => scene({ eyebrow: 'Chapter review', title, passage: `Mark ${chapter}`, summary: 'Retell the chapter in order, using these scene words as a memory path.', details, recall: ['Retell the whole chapter without looking.', 'Name one place, one person, one number, and one saying from this chapter.'] })

export const MARK_7_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'What truly makes a person unclean?', passage: 'Mark 7:1–37', summary: 'Jesus answers a dispute about tradition and purity, then crosses into Gentile regions where persistent faith and compassionate healing reveal that His mercy is not confined by boundaries.', details: ['Tradition and the heart (1–23).', 'The Syrophoenician woman (24–30).', 'A deaf man with a speech impediment (31–37).'], image: image(7, 'chapter-overview', 'Jesus teaching a mixed group near a Galilean village'), recall: ['Name the three movements of Mark 7.', 'What changes location after verse 23?'] }),
  scene({ eyebrow: 'Scene 1', title: 'Tradition, Corban, and the heart', passage: 'Mark 7:1–23', summary: 'Pharisees and scribes question why some disciples eat with unwashed hands. Jesus condemns using human tradition to evade God’s command and teaches that defilement proceeds from the heart.', details: ['The dispute concerns ritual handwashing, not ordinary hygiene.', 'Jesus quotes Isaiah 29:13 and cites the command to honor father and mother.', 'Corban could designate something as given to God; Jesus condemns a use that cancels care owed to parents.', 'The evil things listed in verses 21–22 come from within.'], carefulNote: 'Mark explains Jewish customs for his readers, but his summary should not be used to caricature all Jewish practice. Jesus challenges hypocrisy and a particular misuse of tradition.', culture: [{ title: 'Ritual washing', body: 'The washing in dispute concerns inherited purity practice before eating. It should not be confused with modern germ-prevention.' }, { title: 'Corban', body: 'A dedicatory formula could set property apart as an offering. Jesus’ example attacks religious speech used to avoid the plain duty of honoring parents.' }], connections: [{ label: 'Scripture cross-reference', references: 'Isaiah 29:13; Exodus 20:12', explanation: 'Jesus explicitly quotes Isaiah and invokes the commandment to honor parents.' }, { label: 'Parallel Gospel account', references: 'Matthew 15:1–20', explanation: 'Matthew preserves a close parallel to the dispute and teaching.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'A Gentile mother answers with faith', passage: 'Mark 7:24–30', summary: 'In the region of Tyre, a Greek, Syrophoenician woman begs Jesus to free her daughter from an unclean spirit. She receives His difficult saying with humility and persistence, and her daughter is healed.', details: ['Jesus enters a house and does not want it known, yet He cannot be hidden.', 'The woman is described by gender, language/culture, and regional ancestry.', 'She accepts the children-and-dogs image but points to crumbs under the table.', 'Jesus sends her home; the demon has gone out of her daughter.'], carefulNote: 'The exchange is deliberately challenging. Mark shows neither the woman’s name nor her tone beyond her words; avoid supplying contempt or a modern ethnic slur the text does not state.', culture: [{ title: 'Tyre and a Gentile household', body: 'Tyre belonged to the Phoenician coast. Mark highlights that this petitioner stands outside Israel’s household and nevertheless receives mercy.' }], connections: [{ label: 'Parallel Gospel account', references: 'Matthew 15:21–28', explanation: 'Matthew tells the same encounter and explicitly praises the woman’s faith.' }] }),
  scene({ eyebrow: 'Scene 3', title: '“Be opened”', passage: 'Mark 7:31–37', summary: 'In the Decapolis, people bring a deaf man who speaks with difficulty. Jesus takes him aside, uses touch and visible actions, looks to heaven, sighs, and commands, “Ephphatha.”', details: ['The route is broad and unusual: from Tyre through Sidon toward the Sea of Galilee in the Decapolis region.', 'Jesus attends personally to the man away from the crowd.', 'His ears are opened and his speech becomes clear.', 'Despite Jesus’ command not to tell anyone, the report spreads: “He has done all things well.”'], culture: [{ title: 'Communication through action', body: 'Touching ears and tongue makes the action intelligible to the man. Mark preserves the Aramaic command and translates it for readers.' }], connections: [{ label: 'Old Testament background', references: 'Isaiah 35:5–6', explanation: 'Isaiah promises opened ears and joyful speech when God comes to save; Mark’s language strongly recalls that promise.' }] }),
  review(7, 'From the lips to the heart', ['Hands — the purity dispute.', 'Corban — tradition must not cancel God’s command.', 'Heart — the source of defiling sins.', 'Crumbs — persistent Gentile faith.', 'Ephphatha — ears opened and speech restored.']),
]

MARK_7_LESSON.splice(1, 1,
  scene({
    eyebrow: 'Scene 1A',
    title: 'Why are they asking about washing?',
    passage: 'Mark 7:1–8',
    summary: 'Pharisees and scribes notice that some disciples eat without first performing the customary ritual washing. Jesus answers that outward religious actions must agree with a heart that truly honors God.',
    details: [
      'This is a question about a religious purity custom before eating—not whether ordinary handwashing or cleanliness matters.',
      'Mark explains several inherited washing practices because some of his readers may not know them.',
      'Jesus quotes Isaiah: people can honor God with their lips while their hearts are far from Him.',
      'His criticism is not that every tradition is wrong. The problem comes when a human rule replaces what God commands or becomes an outward performance without faithful love.',
    ],
    carefulNote: 'Do not turn this dispute into a caricature of Jewish people or their traditions. Jesus, His disciples, and His first hearers are Jewish. He is confronting hypocrisy and command-overriding practice in this specific exchange.',
    culture: [{ title: 'Ritual washing is not a hygiene debate', body: 'The washing in this scene expresses inherited purity practice. Mark is not arguing against washing dirt or germs from hands.' }],
    connections: [{ label: 'Scripture cross-reference', references: 'Isaiah 29:13', explanation: 'Jesus directly quotes Isaiah to show the danger of outward worship separated from a faithful heart.' }],
    recall: ['What kind of washing starts the dispute?', 'Does Jesus say that every tradition is wrong? Explain the specific problem He identifies.'],
  }),
  scene({
    eyebrow: 'Scene 1B',
    title: 'Corban: a promise must not cancel care',
    passage: 'Mark 7:9–13',
    summary: 'Jesus gives a concrete example of a tradition overriding God’s command. “Corban” means a gift dedicated to God. He criticizes a use of that declaration that blocks someone from supporting parents in need.',
    details: [
      'God commands, “Honor your father and your mother.” Honoring them includes taking seriously the care they are owed.',
      'Corban means that money or property has been declared dedicated to God.',
      'A simple hypothetical example: imagine an adult has savings that could buy food or medicine for an elderly parent. He declares those savings Corban—dedicated to God—and the rule is then used to say he may not use them to help the parent.',
      'Jesus’ objection is that the human rule has now overridden God’s command. Religious words are being used as an excuse to neglect a person God says to honor.',
      'Child takeaway: We cannot use a religious promise as an excuse to neglect people God tells us to care for.',
    ],
    carefulNote: 'The example above is hypothetical; Mark does not describe a particular family doing this. Jesus is not opposing sincere gifts to God, declaring every vow fraudulent, or rejecting all tradition. He condemns this specific conflict and misuse.',
    culture: [{ title: 'A dedicatory declaration', body: 'Calling resources Corban marked them as dedicated to God. The issue in Jesus’ example is not generosity to God, but a rule that lets that declaration cancel a prior divine duty to one’s parents.' }],
    connections: [{ label: 'Scripture cross-reference', references: 'Exodus 20:12; Deuteronomy 5:16', explanation: 'Jesus explicitly appeals to God’s command to honor father and mother.' }],
    recall: ['What does Corban mean?', 'In the hypothetical savings example, which command is the person neglecting?', 'What exactly does Jesus criticize—and what does He not condemn?'],
  }),
  scene({
    eyebrow: 'Scene 1C',
    title: 'What comes from the heart',
    passage: 'Mark 7:14–23',
    summary: 'Jesus calls the crowd to listen: food entering from outside does not create the moral evil He is describing. Evil thoughts and actions proceed from within—from the human heart.',
    details: [
      'The disciples ask Jesus to explain the saying privately.',
      'Food enters the body and passes through it; it does not enter the heart.',
      'Jesus lists sins such as theft, deceit, pride, envy, and foolishness as things that arise from within.',
      'Outward religious observance cannot substitute for a good heart and right actions. God cares about both our inner choices and how we treat people.',
    ],
    carefulNote: 'Jesus is teaching about moral defilement. This does not make hygiene, bodily care, or thoughtful religious practice unimportant; it locates the source of sinful thoughts and actions in the heart.',
    connections: [{ label: 'Thematic parallel', references: '1 Samuel 16:7; Psalm 51:10', explanation: 'These passages emphasize that God sees the heart and that a clean heart is God’s work in us. Mark does not quote them here.' }, { label: 'Parallel Gospel account', references: 'Matthew 15:10–20', explanation: 'Matthew preserves a close parallel to the teaching about what enters the mouth and what proceeds from the heart.' }],
    recall: ['According to Jesus, where do evil thoughts and actions come from?', 'Why can an outward religious action never replace a good heart and right treatment of others?'],
  }),
)

export const MARK_8_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'Seeing—but not yet clearly', passage: 'Mark 8:1–38', summary: 'A second wilderness meal, demands for a sign, a two-stage healing, Peter’s confession, and the first Passion prediction ask what it means truly to see Jesus.', details: ['Four thousand fed and seven baskets left (1–10).', 'A warning about leaven (11–21).', 'Sight restored in stages at Bethsaida (22–26).', 'Peter confesses Christ; Jesus teaches the cross (27–38).'], image: image(8, 'chapter-overview', 'Jesus and the disciples on the road north near Caesarea Philippi'), recall: ['Put 4,000 and seven baskets in context.', 'Where does Peter confess Jesus as the Christ?'] }),
  scene({ eyebrow: 'Scene 1', title: 'Compassion and seven baskets', passage: 'Mark 8:1–10', summary: 'Jesus has compassion on a crowd that has remained with Him three days and has nothing to eat. Seven loaves and a few small fish become enough for about four thousand people.', details: ['Jesus worries they may faint on the way home; some came from far away.', 'The crowd sits on the ground. Jesus gives thanks, breaks, and gives through the disciples.', 'Seven large baskets of pieces remain.', 'Jesus departs by boat for the region of Dalmanutha.'], carefulNote: 'This is narrated as a second feeding, with different numbers from Mark 6. Do not merge the two accounts.', connections: [{ label: 'Scripture cross-reference', references: 'Mark 6:35–44', explanation: 'Mark expects readers to compare the two feedings while preserving their distinct numbers.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'Leaven and short memories', passage: 'Mark 8:11–21', summary: 'After Pharisees demand a sign, Jesus warns the disciples about the leaven of the Pharisees and Herod. They think He is complaining about bread, exposing how little they have understood.', details: ['Jesus sighs deeply and refuses the testing demand for a sign.', 'The disciples have one loaf in the boat.', 'Jesus reviews both feedings: five loaves, five thousand, twelve baskets; seven loaves, four thousand, seven baskets.', 'His closing question is, “How is it you do not understand?”'], culture: [{ title: 'Leaven as influence', body: 'A small amount of leaven works through dough. Here it functions as a warning image for a corrupting disposition, not a lesson about baking.' }], connections: [{ label: 'Parallel Gospel account', references: 'Matthew 16:1–12', explanation: 'Matthew’s parallel explicitly identifies the warning with the teaching of the Pharisees and Sadducees.' }] }),
  scene({ eyebrow: 'Scene 3', title: 'From blurred sight to the way of the cross', passage: 'Mark 8:22–38', summary: 'A blind man gradually sees clearly. Soon Peter correctly names Jesus as the Christ but rejects His suffering, showing that spiritual sight also needs correction.', details: ['At Bethsaida, the man first sees people “like trees, walking”; after a second touch he sees clearly.', 'Near Caesarea Philippi, Peter answers, “You are the Christ.”', 'Jesus predicts rejection, death, and rising after three days; Peter rebukes Him and is sharply corrected.', 'Disciples must deny themselves, take up the cross, and follow.'], carefulNote: 'Peter’s confession is true but incomplete without the cross. “Take up the cross” was a grave image under Roman rule, not a phrase for any minor inconvenience.', culture: [{ title: 'A Roman cross before Calvary', body: 'People under Roman rule knew crucifixion as public terror and shame. Jesus’ call would sound costly before the disciples understood His own death.' }], connections: [{ label: 'Parallel Gospel account', references: 'Matthew 16:13–28; Luke 9:18–27', explanation: 'Both parallels preserve Peter’s confession, the Passion prediction, and the call to follow.' }] }),
  review(8, 'Learning to see Jesus clearly', ['Bread — 4,000; seven loaves; seven baskets.', 'Leaven — misunderstanding and warning.', 'Bethsaida — sight in two stages.', 'Christ — Peter’s true confession.', 'Cross — the Messiah’s road and the disciple’s road.']),
]

export const MARK_9_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'Glory, faith, and true greatness', passage: 'Mark 9:1–50', summary: 'The Transfiguration reveals Jesus’ glory, a desperate father asks help for unbelief, and Jesus teaches disciples who still compete for status.', details: ['Transfiguration and Elijah question (1–13).', 'A boy delivered after the disciples fail (14–29).', 'Second Passion prediction and teaching in Capernaum (30–50).'], image: image(9, 'chapter-overview', 'Jesus transfigured on a high mountain with three disciples sheltering their eyes'), recall: ['Which three disciples go up the mountain?', 'What does the voice command them to do?'] }),
  scene({ eyebrow: 'Scene 1', title: '“Listen to Him”', passage: 'Mark 9:1–13', summary: 'Peter, James, and John see Jesus transfigured with Elijah and Moses. A cloud overshadows them, and the heavenly voice identifies the beloved Son and commands attention to Him.', details: ['Jesus’ clothes become intensely white.', 'Peter proposes three tabernacles because he does not know what to say; they are afraid.', 'After the voice, they see only Jesus with them.', 'Coming down, Jesus orders silence until the Son of Man rises and explains that Elijah has come.'], carefulNote: 'Mark does not name the mountain. The Orthodox tradition celebrates the event at Mount Tabor, but the Gospel text itself leaves the site unstated.', connections: [{ label: 'Old Testament background', references: 'Exodus 24:15–18; 1 Kings 19:8–13', explanation: 'Mountain, cloud, revelation, Moses, and Elijah evoke Israel’s encounters with God.' }, { label: 'Parallel Gospel account', references: 'Matthew 17:1–13; Luke 9:28–36', explanation: 'Both Synoptic Gospels narrate the Transfiguration with complementary details.' }] }),
  scene({ eyebrow: 'Scene 2', title: '“Help my unbelief!”', passage: 'Mark 9:14–29', summary: 'A father brings his suffering son after the disciples cannot help. He cries, “Lord, I believe; help my unbelief!” Jesus rebukes the spirit, raises the boy, and teaches the disciples about prayer.', details: ['The symptoms are described dramatically, but Mark presents the cause in this case as an unclean spirit.', 'The father asks for compassion and help; Jesus turns the question toward faith.', 'After the spirit leaves, many think the boy is dead, but Jesus takes his hand and raises him.', 'Privately the disciples ask why they failed.'], carefulNote: 'Do not use this story to diagnose epilepsy or other illness as demonic. Mark reports one particular encounter, not a medical rule.', connections: [{ label: 'Text note', references: 'Mark 9:29', explanation: 'The NKJV/Orthodox textual tradition reads “prayer and fasting”; some early manuscripts have “prayer” without “and fasting.”' }] }),
  scene({ eyebrow: 'Scene 3', title: 'Last of all and servant of all', passage: 'Mark 9:30–50', summary: 'Jesus again predicts His death and resurrection. The disciples are afraid to ask, argue about greatness, and learn to receive the lowly, reject rivalry, resist sin, and live at peace.', details: ['In Capernaum Jesus sits, calls the Twelve, and places a child in their midst.', 'Receiving such a child in His name receives Jesus and the One who sent Him.', 'Someone casting out demons in Jesus’ name must not be stopped merely because he is outside their group.', 'Jesus uses severe images to teach decisive resistance to sin and commands, “Have peace with one another.”'], carefulNote: 'The hand, foot, and eye sayings are forceful moral hyperbole calling for radical repentance; they are not instructions for self-injury.', culture: [{ title: 'A child in the middle', body: 'Children were loved, but they did not hold adult status. Receiving a child makes greatness visible as welcome and service rather than rank.' }], connections: [{ label: 'Parallel Gospel account', references: 'Matthew 18:1–9; Luke 9:46–50', explanation: 'The parallels preserve the child, the argument over greatness, and the outsider acting in Jesus’ name.' }] }),
  review(9, 'Listen, pray, serve', ['Mountain — glory and the beloved Son.', 'Father — belief asking help for unbelief.', 'Prayer — dependence where the disciples failed.', 'Child — receive the lowly.', 'Salt and peace — faithful discipleship together.']),
]

export const MARK_10_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'The road of costly discipleship', passage: 'Mark 10:1–52', summary: 'On the way toward Jerusalem, Jesus teaches covenant faithfulness, welcomes children, challenges wealth, predicts His Passion, redefines greatness, and restores Bartimaeus’s sight.', details: ['Marriage and children (1–16).', 'The rich man and reward of discipleship (17–31).', 'Third Passion prediction and servant leadership (32–45).', 'Bartimaeus follows on the road (46–52).'], image: image(10, 'chapter-overview', 'Jesus walking toward Jerusalem with disciples and travelers on a Judean road'), recall: ['What does the rich man lack?', 'What request do James and John make?'] }),
  scene({ eyebrow: 'Scene 1', title: 'Faithfulness and the kingdom', passage: 'Mark 10:1–16', summary: 'Jesus answers a test about divorce by returning to God’s creation purpose, then welcomes children whom the disciples try to turn away.', details: ['Moses’ concession addresses hardness of heart; Jesus cites Genesis about two becoming one flesh.', 'In the house, Jesus explains the seriousness of divorcing and marrying another.', 'Jesus is greatly displeased when disciples rebuke those bringing children.', 'The kingdom must be received like a little child.'], carefulNote: 'Teach the marriage passage with pastoral care. Jesus confronts hard-hearted disposal of spouses; the scene should not be weaponized against children or adults living through family fracture.', connections: [{ label: 'Scripture cross-reference', references: 'Genesis 1:27; 2:24', explanation: 'Jesus directly grounds His answer in the creation accounts.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'The man Jesus loved', passage: 'Mark 10:17–31', summary: 'A wealthy man asks about eternal life. Jesus loves him, exposes the possession that possesses him, and invites him to give, follow, and receive treasure in heaven.', details: ['The man kneels and addresses Jesus as Good Teacher.', 'He says he has kept the named commandments from youth.', 'Jesus tells him to sell, give to the poor, and follow; he leaves sorrowful because he has many possessions.', 'Jesus says salvation is impossible with humans but not with God, and promises reward with persecutions.'], carefulNote: 'The text says Jesus loved the man. The challenge is not permission to despise wealthy people; it exposes idolatry and calls this person into liberating discipleship.', connections: [{ label: 'Parallel Gospel account', references: 'Matthew 19:16–30; Luke 18:18–30', explanation: 'The parallels preserve the encounter and the disciples’ astonishment.' }] }),
  scene({ eyebrow: 'Scenes 3–4', title: 'A ransom, then sight on the road', passage: 'Mark 10:32–52', summary: 'Jesus predicts His mocking, scourging, death, and resurrection. James and John seek places of honor; Jesus answers with the cup, baptism, service, and His life as a ransom. At Jericho, Bartimaeus sees and follows.', details: ['The disciples are amazed and afraid as Jesus goes ahead toward Jerusalem.', 'The rulers of the Gentiles “lord it over” others; greatness among Jesus’ followers means serving.', 'The Son of Man came not to be served but to serve and to give His life as a ransom for many.', 'Blind Bartimaeus calls Jesus “Son of David,” throws aside his garment, receives sight, and follows on the road.'], culture: [{ title: 'Jericho’s roadside', body: 'Crowds moving through Jericho make a roadside beggar visible yet easy to silence. Mark names Bartimaeus and preserves his repeated cry.' }], connections: [{ label: 'Old Testament background', references: 'Isaiah 53:10–12', explanation: 'The servant who gives his life for many provides important background for the ransom saying.' }] }),
  review(10, 'On the road with the Servant King', ['Covenant — joined by God.', 'Children — receive the kingdom.', 'Possessions — one thing lacking.', 'Ransom — greatness as service.', 'Bartimaeus — sight and following.']),
]

export const MARK_11_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'The King enters and inspects His house', passage: 'Mark 11:1–33', summary: 'Jesus enters Jerusalem on a colt, judges fruitlessness through the fig tree and temple actions, and answers leaders who challenge His authority.', details: ['Entry from the Mount of Olives (1–11).', 'Fig tree and temple interwoven (12–26).', 'Authority challenged in the temple (27–33).'], image: image(11, 'chapter-overview', 'Jesus entering Jerusalem humbly on a colt among pilgrims carrying branches'), recall: ['What animal does Jesus ride?', 'What words do the crowd shout from Psalm 118?'] }),
  scene({ eyebrow: 'Scene 1', title: 'Hosanna on the road', passage: 'Mark 11:1–11', summary: 'Near Bethphage and Bethany, Jesus sends two disciples for an unridden colt. He enters Jerusalem amid cloaks, leafy branches, and shouts of blessing, then looks around the temple and returns to Bethany.', details: ['The disciples are told exactly how to answer if questioned about the colt.', 'People spread garments and branches on the road.', 'They bless the coming kingdom of David and cry “Hosanna.”', 'Because it is late, Jesus leaves the temple with the Twelve.'], culture: [{ title: 'Pilgrim welcome and royal symbolism', body: 'Cloaks and branches create a public welcome; the colt evokes a humble king. “Hosanna” began as a plea to save and became an acclamation.' }], connections: [{ label: 'Old Testament background', references: 'Zechariah 9:9; Psalm 118:25–26', explanation: 'The colt and crowd’s words draw on royal and pilgrimage Scripture.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'No fruit and a disrupted court', passage: 'Mark 11:12–26', summary: 'The fig tree episode surrounds Jesus’ action in the temple. He overturns commerce that obstructs the house of prayer and quotes Scripture against a den of thieves.', details: ['Jesus finds leaves but no figs; Mark notes it was not the season for figs.', 'In the temple He stops buying, selling, money-changing, dove-selling, and carrying wares through the precinct.', 'He quotes Isaiah’s “house of prayer for all nations” and Jeremiah’s “den of thieves.”', 'The next morning the disciples see the fig tree withered from the roots; Jesus teaches faith, prayer, and forgiveness.'], carefulNote: 'The fig tree functions symbolically in Mark’s interwoven story; it is not a lesson in blaming a tree for seasonal biology.', culture: [{ title: 'Money and sacrificial animals', body: 'Pilgrims needed acceptable offerings and currency. Jesus’ action condemns what the system has become in the sacred space; Mark does not reduce it to a complaint that any exchange is inherently wrong.' }], connections: [{ label: 'Scripture cross-reference', references: 'Isaiah 56:7; Jeremiah 7:11', explanation: 'Jesus directly joins the temple’s worldwide vocation with Jeremiah’s judgment oracle.' }] }),
  scene({ eyebrow: 'Scene 3', title: 'Who gave You this authority?', passage: 'Mark 11:27–33', summary: 'Chief priests, scribes, and elders demand Jesus’ authorization. He asks whether John’s baptism came from heaven or humans, exposing their refusal to answer honestly.', details: ['The exchange occurs while Jesus walks in the temple.', 'The leaders reason politically: either answer will cost them.', 'They say, “We do not know.”', 'Jesus therefore declines to answer their challenge on their terms.'], connections: [{ label: 'Scripture cross-reference', references: 'Mark 1:4–11', explanation: 'John’s baptism and the heavenly declaration at Jesus’ baptism stand behind the counter-question.' }] }),
  review(11, 'Entry, judgment, authority', ['Colt — humble royal entry.', 'Hosanna — save and bless.', 'Fig tree — leaves without fruit.', 'Temple — prayer for all nations.', 'John — the authority question returned.']),
]

export const MARK_12_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'Love God, love neighbor, give truly', passage: 'Mark 12:1–44', summary: 'In the temple, Jesus tells a vineyard parable, answers traps about Caesar and resurrection, names the greatest commandments, questions the scribes, and notices a widow’s gift.', details: ['Vineyard tenants (1–12).', 'Caesar and resurrection (13–27).', 'Greatest commandment and David’s Son (28–37).', 'Scribes and the widow (38–44).'], image: image(12, 'chapter-overview', 'Jesus teaching attentive listeners in the broad courts of the Jerusalem temple'), recall: ['Whose image is on the denarius?', 'What two commandments are greatest?'] }),
  scene({ eyebrow: 'Scene 1', title: 'The rejected stone', passage: 'Mark 12:1–12', summary: 'Tenants beat the owner’s servants and kill his beloved son, hoping to seize the vineyard. Jesus quotes the rejected stone becoming the cornerstone.', details: ['The vineyard has a hedge, wine vat, and tower before it is leased.', 'Servants are beaten, wounded, shamed, or killed.', 'The owner finally sends his beloved son.', 'The leaders know the parable is against them but fear the crowd.'], carefulNote: 'The parable judges unfaithful leaders. It must not be turned into contempt for Jewish people as a whole; Jesus and His first followers are Jewish, and the stated opponents are specific leaders.', connections: [{ label: 'Old Testament background', references: 'Isaiah 5:1–7; Psalm 118:22–23', explanation: 'The vineyard and rejected-stone quotation interpret judgment and God’s surprising vindication.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'Two traps, two answers', passage: 'Mark 12:13–27', summary: 'Pharisees and Herodians ask about Roman tax; Sadducees pose a resurrection puzzle. Jesus exposes the traps and answers from God’s ownership, Scripture, and power.', details: ['A denarius bears Caesar’s image and inscription.', 'Jesus commands what belongs to Caesar to Caesar and what belongs to God to God.', 'The Sadducees, who deny resurrection, build a case from seven brothers and one widow.', 'Jesus cites God as the God of Abraham, Isaac, and Jacob: God is God of the living.'], culture: [{ title: 'A denarius and imperial claims', body: 'The tax coin carried the emperor’s portrait and titles. Jesus asks whose image it bears while insisting that God’s claim cannot be reduced to Caesar’s coin.' }, { title: 'Levirate marriage', body: 'The seven-brother question draws on the duty to preserve a deceased brother’s family line. The Sadducees use it as a puzzle against resurrection.' }], connections: [{ label: 'Scripture cross-reference', references: 'Deuteronomy 25:5–10; Exodus 3:6', explanation: 'The question uses levirate law; Jesus answers from God’s words at the burning bush.' }] }),
  scene({ eyebrow: 'Scenes 3–4', title: 'The center of the Law—and two small coins', passage: 'Mark 12:28–44', summary: 'Jesus joins wholehearted love of God to love of neighbor. He then warns against honor-seeking scribes and sees a poor widow give all she has.', details: ['The Shema begins, “Hear, O Israel: the LORD our God, the LORD is one.”', 'Love of God involves heart, soul, mind, and strength; love of neighbor follows.', 'The scribe says this love exceeds burnt offerings and sacrifices; Jesus says he is not far from the kingdom.', 'The widow contributes two mites, worth a quadrans; Jesus measures her gift by sacrifice, not amount.'], carefulNote: 'Jesus praises the widow’s total gift immediately after condemning scribes who devour widows’ houses. Teach both observations; do not pressure vulnerable people to surrender necessities to exploitative leaders.', connections: [{ label: 'Scripture cross-reference', references: 'Deuteronomy 6:4–5; Leviticus 19:18; Psalm 110:1', explanation: 'Jesus directly quotes the two love commands and then uses Psalm 110 to ask about David’s Son.' }] }),
  review(12, 'The heart God seeks', ['Vineyard — rejected beloved son.', 'Coin — Caesar’s image, God’s claim.', 'Living — resurrection and God’s power.', 'Love — God and neighbor.', 'Widow — two coins, everything she had.']),
]

export const MARK_13_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'Watch, endure, and do not be deceived', passage: 'Mark 13:1–37', summary: 'Opposite the temple, Jesus warns of its destruction, coming trials, false claims, cosmic upheaval, and the need for alert faithfulness.', details: ['Temple prediction and beginning of sorrows (1–13).', 'Crisis in Judea and false christs (14–23).', 'The Son of Man and the fig tree lesson (24–31).', 'Unknown day and hour: watch (32–37).'], image: image(13, 'chapter-overview', 'Jesus seated with four disciples on the Mount of Olives overlooking the temple'), recall: ['Which four disciples ask Jesus privately?', 'What repeated command closes the discourse?'] }),
  scene({ eyebrow: 'Scene 1', title: 'Do not be deceived', passage: 'Mark 13:1–13', summary: 'After predicting the temple’s destruction, Jesus privately teaches Peter, James, John, and Andrew that upheaval and persecution are not permission for panic or date-setting.', details: ['False claimants, wars, earthquakes, and famines are beginnings, not the end itself.', 'Disciples will face councils, synagogues, rulers, and kings.', 'The gospel must first be preached to all nations.', 'The Holy Spirit will give testimony; the one who endures to the end will be saved.'], carefulNote: 'Jesus explicitly says not to be troubled and later says no one knows the day or hour. The passage should not be converted into confident predictions tied to each current headline.', connections: [{ label: 'Parallel Gospel account', references: 'Matthew 24:1–14; Luke 21:5–19', explanation: 'The parallels preserve the temple setting, warnings, and call to endurance.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'A severe crisis—and shortened days', passage: 'Mark 13:14–23', summary: 'Jesus gives urgent flight instructions concerning the “abomination of desolation,” warns of unparalleled distress, and repeats that false christs and prophets must not deceive His followers.', details: ['Readers are told to understand Daniel’s phrase.', 'Those in Judea flee; rooftop and field images stress urgency.', 'Pregnancy, nursing, and winter intensify hardship.', 'God shortens the days for the elect; Jesus says He has told them beforehand.'], carefulNote: 'The passage has been related to Jerusalem’s first-century catastrophe and to final tribulation. Presenting either horizon should be labeled interpretation; Mark does not supply a modern calendar.', connections: [{ label: 'Old Testament background', references: 'Daniel 9:27; 11:31; 12:11', explanation: 'The “abomination of desolation” language comes from Daniel’s visions.' }] }),
  scene({ eyebrow: 'Scenes 3–4', title: 'The Son of Man comes: therefore watch', passage: 'Mark 13:24–37', summary: 'Cosmic signs accompany the Son of Man’s coming and the gathering of the elect. The fig tree teaches attentiveness, while the unknown hour forbids complacency and calculation.', details: ['The Son of Man comes in clouds with great power and glory.', 'Angels gather the elect from the ends of earth and heaven.', 'Jesus says His words will not pass away.', 'Not even the angels or the Son know the day or hour; servants must stay awake for the master’s return.'], connections: [{ label: 'Old Testament background', references: 'Daniel 7:13–14; Isaiah 13:10', explanation: 'Cloud-coming and cosmic imagery draw on prophetic descriptions of divine judgment and kingdom.' }, { label: 'Text note', references: 'Mark 13:32–37', explanation: 'The emphasis is ethical readiness—faithful work and watchfulness—not discovering a secret date.' }] }),
  review(13, 'A faithful watcher’s path', ['Stones — the temple will fall.', 'Birth pains — upheaval is not the end.', 'Witness — Spirit-given testimony.', 'Fig tree — recognize nearness.', 'Watch — the hour is unknown.']),
]

export const MARK_14_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'Gift, covenant, prayer, betrayal', passage: 'Mark 14:1–72', summary: 'As leaders plot, a woman honors Jesus for burial. Jesus gives the Passover meal new covenant meaning, prays in Gethsemane, is betrayed and condemned, while Peter denies Him.', details: ['Anointing at Bethany and Judas’s agreement (1–11).', 'Passover and the Lord’s Supper (12–26).', 'Gethsemane, arrest, and flight (27–52).', 'Council hearing and Peter’s denials (53–72).'], image: image(14, 'chapter-overview', 'Jesus sharing the Passover meal with the Twelve in a lamp-lit upper room'), recall: ['What does the woman pour on Jesus?', 'How many times does Peter deny knowing Him?'] }),
  scene({ eyebrow: 'Scene 1', title: 'A beautiful work before burial', passage: 'Mark 14:1–11', summary: 'At Simon the leper’s house in Bethany, a woman breaks an alabaster flask and pours costly spikenard on Jesus’ head. Jesus defends her act as preparation for burial; Judas then seeks to betray Him.', details: ['The perfume is valued at more than three hundred denarii.', 'Some criticize the “waste” and invoke the poor.', 'Jesus says opportunities to help the poor remain, but His bodily presence is brief.', 'He promises her deed will be remembered wherever the gospel is preached.'], carefulNote: 'Mark does not name the woman. Do not silently identify her from a different Gospel account.', culture: [{ title: 'Costly perfume and burial honor', body: 'An alabaster container and imported aromatic oil signaled extraordinary expense. Jesus interprets the act in light of His approaching burial.' }], connections: [{ label: 'Parallel Gospel account', references: 'Matthew 26:6–16; John 12:1–8', explanation: 'Matthew closely parallels Mark. John narrates a related Bethany anointing and names Mary; keep each Gospel’s details distinct.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'Passover becomes covenant meal', passage: 'Mark 14:12–31', summary: 'Jesus prepares Passover with the Twelve, identifies a betrayer at the table, gives bread and cup as His body and covenant blood, sings a hymn, and predicts desertion and Peter’s three denials.', details: ['A man carrying a pitcher leads two disciples to a furnished upper room.', 'The betrayer is one of the Twelve who dips with Jesus.', 'Jesus says the cup is His blood of the new covenant, shed for many.', 'After singing, they go to the Mount of Olives; Jesus promises to go before them to Galilee after rising.'], carefulNote: 'The NKJV/Orthodox text reads “blood of the new covenant.” Some critical editions read “blood of the covenant.” The covenant meaning is present in either wording.', culture: [{ title: 'Passover table', body: 'The meal remembers Israel’s deliverance. Jesus interprets bread and cup around His own coming death; Orthodox Christianity receives this as the institution of the Eucharist.' }], connections: [{ label: 'Old Testament background', references: 'Exodus 12:1–28; 24:8; Zechariah 13:7', explanation: 'Passover, covenant blood, and the struck shepherd all stand directly behind Jesus’ words.' }, { label: 'Orthodox study note', references: 'Mark 14:22–24', explanation: 'Orthodox teaching receives the bread and cup sacramentally as Christ’s Body and Blood, not as an empty remembrance.' }] }),
  scene({ eyebrow: 'Scenes 3–4', title: 'Gethsemane to the courtyard', passage: 'Mark 14:32–72', summary: 'Jesus prays in anguish and submits to the Father. Judas arrives with an armed crowd; the disciples flee. Jesus confesses His identity before the council, while Peter denies Him outside.', details: ['Jesus takes Peter, James, and John farther into Gethsemane and prays three times.', 'He addresses God as “Abba, Father” and asks that the cup pass, yet submits to the Father’s will.', 'A disciple cuts the high priest’s servant; a young man escapes naked after his linen cloth is seized.', 'The high priest asks if Jesus is the Christ. Jesus answers and speaks of the Son of Man; Peter’s third denial is followed by the second rooster crow, and he weeps.'], carefulNote: 'Keep the arrest and abuse truthful but non-graphic for a young learner. Mark leaves the sword-user and fleeing young man unnamed.', connections: [{ label: 'Old Testament background', references: 'Psalm 42:5; Daniel 7:13–14; Psalm 110:1', explanation: 'Jesus’ sorrow and His council declaration echo Israel’s prayers and royal visions.' }] }),
  review(14, 'Remember, watch, and remain', ['Perfume — prepared for burial.', 'Bread and cup — body and covenant blood.', 'Abba — obedient prayer.', 'Kiss — betrayal and arrest.', 'Rooster — three denials and tears.']),
]

export const MARK_15_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'The crucified King', passage: 'Mark 15:1–47', summary: 'Jesus is handed to Pilate, mocked as King of the Jews, crucified at Golgotha, dies after darkness covers the land, and is buried by Joseph of Arimathea while women watch.', details: ['Pilate, Barabbas, and the sentence (1–15).', 'Mocking and crucifixion (16–32).', 'Death, torn veil, and the centurion’s confession (33–41).', 'Joseph’s tomb and the women witnesses (42–47).'], image: image(15, 'chapter-overview', 'the three crosses seen from a respectful distance under a darkened Jerusalem sky'), recall: ['Who carries Jesus’ cross?', 'Who asks Pilate for Jesus’ body?'] }),
  scene({ eyebrow: 'Scene 1', title: 'The crowd chooses Barabbas', passage: 'Mark 15:1–15', summary: 'The council delivers Jesus to Pilate. Though Pilate recognizes the leaders’ envy and asks what evil Jesus has done, he releases Barabbas and hands Jesus over to be crucified.', details: ['Pilate asks, “Are You the King of the Jews?” Jesus answers, “It is as you say.”', 'Jesus gives no further answer to many accusations, astonishing Pilate.', 'Barabbas is imprisoned with rebels who committed murder in an uprising.', 'Pilate chooses to gratify the crowd.'], carefulNote: 'Mark assigns agency to particular leaders, Pilate, soldiers, and the crowd in this scene. It is historically and theologically wrong to blame Jewish people collectively for Jesus’ death.', culture: [{ title: 'Roman prefect and public order', body: 'Pilate held Roman coercive power. Crucifixion was a Roman punishment, and Mark portrays his political calculation rather than innocence.' }], connections: [{ label: 'Old Testament background', references: 'Isaiah 53:7', explanation: 'Jesus’ silence before accusers recalls the suffering servant who does not open his mouth.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'Mocked as King, crucified at Golgotha', passage: 'Mark 15:16–32', summary: 'Soldiers dress Jesus in purple, crown Him with thorns, and mock His kingship. Simon of Cyrene carries the cross; Jesus is crucified between two robbers beneath the charge “King of the Jews.”', details: ['Mark names Simon as father of Alexander and Rufus.', 'Golgotha is translated “Place of a Skull.”', 'Jesus refuses wine mixed with myrrh.', 'His garments are divided by lot; He is crucified at the third hour, and passersby and leaders mock Him.'], carefulNote: 'The illustration and lesson remain non-graphic. The text’s purpose is not sensational violence but the faithful King’s suffering and the irony of mock homage.', connections: [{ label: 'Old Testament background', references: 'Psalm 22:7–8, 18; Isaiah 53:12', explanation: 'Mocking, divided garments, and being numbered with transgressors echo these passages.' }] }),
  scene({ eyebrow: 'Scenes 3–4', title: 'Death, confession, and burial', passage: 'Mark 15:33–47', summary: 'Darkness falls from the sixth to ninth hour. Jesus cries from Psalm 22 and dies; the temple veil tears, and a centurion confesses Him as Son of God. Joseph of Arimathea courageously provides a tomb.', details: ['Jesus’ Aramaic cry is translated: “My God, My God, why have You forsaken Me?”', 'The veil tears from top to bottom.', 'Women who had followed and served Jesus watch from a distance; Mark names Mary Magdalene, Mary mother of James the Less and Joses, and Salome.', 'Pilate confirms death with the centurion. Joseph wraps the body in linen and lays it in a rock-hewn tomb; two Marys see where.'], carefulNote: 'Jesus’ cry quotes Psalm 22; teach its real anguish without saying the Father ceased to love the Son. Mark reports death plainly and supplies witnesses who connect burial to the empty tomb.', connections: [{ label: 'Scripture cross-reference', references: 'Psalm 22:1; Mark 1:1, 11', explanation: 'The cry begins Psalm 22, while the centurion’s confession echoes Mark’s opening title and the baptismal voice.' }] }),
  review(15, 'Witnesses at the cross and tomb', ['Barabbas — released.', 'Simon — carries the cross.', 'Golgotha — King of the Jews.', 'Veil — torn from top to bottom.', 'Joseph and the women — burial witnessed.']),
]

export const MARK_16_LESSON: MarkLessonSlide[] = [
  scene({ eyebrow: 'Chapter map', title: 'He is risen', passage: 'Mark 16:1–20', summary: 'Women discover the opened tomb and hear that Jesus has risen. The chapter then records appearances, commission, signs, Ascension, and worldwide preaching—with an important manuscript note about verses 9–20.', details: ['Women at the empty tomb (1–8).', 'Appearances and unbelief rebuked (9–14).', 'Commission, signs, Ascension, and preaching (15–20).'], image: image(16, 'chapter-overview', 'three women approaching an opened rock-cut tomb at dawn without depicting Jesus'), recall: ['Which women bring spices?', 'What message does the young man give them?'] }),
  scene({ eyebrow: 'Scene 1', title: 'The stone is already rolled away', passage: 'Mark 16:1–8', summary: 'After the Sabbath, Mary Magdalene, Mary the mother of James, and Salome bring spices. They find the very large stone moved and hear that Jesus the Nazarene, who was crucified, has risen.', details: ['They come very early on the first day of the week, when the sun has risen.', 'They worry about who will roll away the stone.', 'A young man in a white robe points to the place where Jesus had lain.', 'He tells them to inform the disciples and Peter that Jesus goes before them to Galilee.', 'They flee trembling and amazed; verse 8 says fear initially silences them.'], carefulNote: 'Mark does not narrate the moment Jesus leaves the tomb. The scene image therefore shows the women approaching the opened tomb, not an invented camera-view of the Resurrection itself.', connections: [{ label: 'Parallel Gospel account', references: 'Matthew 28:1–10; Luke 24:1–12; John 20:1–18', explanation: 'All four Gospels proclaim the empty tomb and Resurrection, while preserving different selected witnesses and details. Read each account on its own terms before comparing.' }] }),
  scene({ eyebrow: 'Scene 2', title: 'Appearances and a rebuke for unbelief', passage: 'Mark 16:9–14', summary: 'The risen Jesus appears first to Mary Magdalene, then in another form to two travelers, and finally to the Eleven, rebuking their refusal to believe those who saw Him.', details: ['Mary Magdalene tells mourning disciples, but they do not believe.', 'Two disciples report an appearance in another form, and the others still do not believe.', 'Jesus appears as the Eleven sit at table.', 'His rebuke concerns unbelief and hardness of heart toward eyewitness testimony.'], carefulNote: 'The traditional Orthodox/NKJV text includes verses 9–20. The earliest surviving Greek manuscripts end at 16:8, while many ancient witnesses preserve the longer ending. The app includes the received ending and labels the textual evidence rather than hiding it.', connections: [{ label: 'Text note', references: 'Mark 16:9–20', explanation: 'This passage belongs to the traditional canonical text used in Orthodox worship and the NKJV/OSB, while its manuscript history should be acknowledged.' }, { label: 'Parallel Gospel account', references: 'Luke 24:13–43; John 20:11–29', explanation: 'Other Gospels independently narrate appearances to Mary, travelers, and assembled disciples, though details should not be merged without notice.' }] }),
  scene({ eyebrow: 'Scene 3', title: 'Proclaim the gospel to every creature', passage: 'Mark 16:15–20', summary: 'Jesus commissions worldwide proclamation, promises accompanying signs, is received into heaven, and sits at God’s right hand. The disciples preach everywhere as the Lord works with them.', details: ['The mission’s scope is “all the world” and “every creature.”', 'The passage joins belief and baptism with salvation and warns about unbelief.', 'Signs include casting out demons, new tongues, divine protection, and healing the sick.', 'The Lord is received into heaven; the disciples go out, and the Lord confirms the word.'], carefulNote: 'Verses about serpents and poison describe divine protection in mission; they do not command believers to manufacture danger or test God. Deliberate snake-handling is not required by the text.', connections: [{ label: 'Old Testament background', references: 'Psalm 110:1', explanation: 'Sitting at God’s right hand uses royal enthronement language already cited by Jesus in Mark 12 and 14.' }, { label: 'Parallel Gospel account', references: 'Matthew 28:18–20; Luke 24:44–53; Acts 1:6–11', explanation: 'These passages offer complementary commission and Ascension accounts.' }] }),
  review(16, 'From the tomb to all the world', ['Spices — three named women.', 'Stone — already rolled away.', 'Galilee — promised meeting.', 'Witnesses — unbelief confronted.', 'Commission — preach everywhere; the Lord works with them.']),
]

MARK_8_LESSON.splice(3, 1,
  scene({ eyebrow: 'Scene 3', title: 'Sight restored in two stages', passage: 'Mark 8:22–26', summary: 'At Bethsaida, Jesus leads a blind man outside the town. After a first touch he sees people indistinctly, “like trees, walking”; after a second, he sees clearly.', details: ['People beg Jesus to touch the man.', 'Jesus takes him by the hand and leads him outside the town.', 'The unusual two-stage healing is narrated without explaining why it happens gradually.', 'Jesus sends him home and tells him not to enter the town.'], carefulNote: 'Do not turn the two stages into a formula for healing. In Mark’s sequence, the gradual sight also prepares readers for Peter’s true but incomplete understanding.', connections: [{ label: 'Text note', references: 'Mark 8:18, 22–26', explanation: 'The disciples’ failure to “see” frames this unique healing and the confession that follows.' }] }),
  scene({ eyebrow: 'Scene 4', title: 'The Christ and the way of the cross', passage: 'Mark 8:27–38', summary: 'Near Caesarea Philippi, Peter names Jesus as the Christ but rejects His suffering. Jesus corrects him and calls the crowd and disciples to self-denial, the cross, and faithful following.', details: ['Peter answers, “You are the Christ.”', 'Jesus predicts rejection, death, and rising after three days.', 'Peter rebukes Jesus and is corrected for setting his mind on human rather than divine things.', 'Saving one’s life means losing it for Jesus and the gospel.'], carefulNote: '“Take up the cross” was a grave image under Roman rule, not a phrase for any minor inconvenience.', culture: [{ title: 'A Roman cross before Calvary', body: 'People under Roman rule knew crucifixion as public terror and shame. Jesus’ call would sound costly before the disciples understood His own death.' }], connections: [{ label: 'Parallel Gospel account', references: 'Matthew 16:13–28; Luke 9:18–27', explanation: 'Both parallels preserve Peter’s confession, the Passion prediction, and the call to follow.' }] }),
)

MARK_9_LESSON.splice(3, 1,
  scene({ eyebrow: 'Scene 3', title: 'Who is greatest?', passage: 'Mark 9:30–37', summary: 'After Jesus again predicts His death and resurrection, the disciples argue about greatness. Jesus sits, calls the Twelve, and places a child among them.', details: ['The disciples do not understand and are afraid to ask.', 'To be first, one must be last of all and servant of all.', 'Receiving a child in Jesus’ name receives Jesus and the One who sent Him.'], culture: [{ title: 'A child in the middle', body: 'Children were loved, but they did not hold adult status. Receiving a child makes greatness visible as welcome and service rather than rank.' }] }),
  scene({ eyebrow: 'Scene 4', title: 'Not against us—and at peace', passage: 'Mark 9:38–50', summary: 'Jesus rejects possessive rivalry over someone acting in His name, values the smallest act of mercy, and uses severe images to demand resistance to sin and peace among disciples.', details: ['“He who is not against us is on our side.”', 'A cup of water given because one belongs to Christ will not lose its reward.', 'Causing a little one to stumble is treated with extreme seriousness.', 'Jesus closes: “Have salt in yourselves, and have peace with one another.”'], carefulNote: 'The hand, foot, and eye sayings are forceful moral hyperbole calling for radical repentance; they are not instructions for self-injury.' }),
)

MARK_10_LESSON.splice(3, 1,
  scene({ eyebrow: 'Scene 3', title: 'The Son of Man came to serve', passage: 'Mark 10:32–45', summary: 'On the road up to Jerusalem, Jesus gives His third detailed Passion prediction. James and John seek honor; Jesus redefines greatness through service and His life given as a ransom.', details: ['Jesus goes ahead; the disciples are amazed and afraid.', 'He predicts mocking, scourging, death, and rising on the third day.', 'James and John ask to sit at His right and left in glory.', 'Greatness means serving; the Son of Man gives His life as a ransom for many.'], connections: [{ label: 'Old Testament background', references: 'Isaiah 53:10–12', explanation: 'The servant who gives his life for many provides important background for the ransom saying.' }] }),
  scene({ eyebrow: 'Scene 4', title: 'Bartimaeus follows on the road', passage: 'Mark 10:46–52', summary: 'Leaving Jericho, blind Bartimaeus repeatedly calls Jesus “Son of David.” Jesus stops, calls him, restores his sight, and Bartimaeus follows on the road.', details: ['Mark names him as the son of Timaeus.', 'The crowd first warns him to be quiet, then tells him to take courage.', 'He throws aside his garment, rises, and comes to Jesus.', 'Jesus says his faith has made him well.'], culture: [{ title: 'Jericho’s roadside', body: 'Crowds moving through Jericho make a roadside beggar visible yet easy to silence. Mark preserves both his name and repeated cry.' }] }),
)

MARK_12_LESSON.splice(3, 1,
  scene({ eyebrow: 'Scene 3', title: 'The greatest commandments', passage: 'Mark 12:28–37', summary: 'A scribe asks which commandment is first. Jesus joins wholehearted love of the one God to love of neighbor, then uses Psalm 110 to ask how the Christ is David’s Son.', details: ['Love involves heart, soul, mind, and strength.', 'The scribe says this love exceeds burnt offerings and sacrifices.', 'Jesus says he is not far from the kingdom.', 'The common people hear Jesus gladly as He questions the scribes.'], connections: [{ label: 'Scripture cross-reference', references: 'Deuteronomy 6:4–5; Leviticus 19:18; Psalm 110:1', explanation: 'Jesus directly quotes the love commands and then David’s psalm.' }] }),
  scene({ eyebrow: 'Scene 4', title: 'A widow gives two small coins', passage: 'Mark 12:38–44', summary: 'After warning that honor-seeking scribes devour widows’ houses, Jesus watches a poor widow give two mites—all she has to live on.', details: ['Scribes seek long robes, public greetings, chief seats, and places of honor.', 'Many rich people put in much.', 'The widow’s two mites equal a quadrans.', 'Jesus measures her gift by its cost to her, not by its size.'], carefulNote: 'Read the praise beside Jesus’ condemnation of leaders who exploit widows. Do not use this scene to pressure vulnerable people into surrendering necessities.', culture: [{ title: 'Tiny coins, complete gift', body: 'Mark translates the value for readers. The coins are materially small, yet her proportional sacrifice exceeds the larger gifts.' }] }),
)

MARK_13_LESSON.splice(3, 1,
  scene({ eyebrow: 'Scene 3', title: 'The Son of Man comes', passage: 'Mark 13:24–31', summary: 'After tribulation, cosmic signs accompany the Son of Man coming in clouds with power and glory, and angels gather the elect.', details: ['The imagery includes darkened sun and moon and shaken heavenly powers.', 'The Son of Man comes in clouds.', 'The fig tree teaches recognition of nearness.', 'Heaven and earth pass away, but Jesus’ words do not.'], connections: [{ label: 'Old Testament background', references: 'Daniel 7:13–14; Isaiah 13:10', explanation: 'Cloud-coming and cosmic imagery draw on prophetic descriptions of divine judgment and kingdom.' }] }),
  scene({ eyebrow: 'Scene 4', title: 'No one knows: watch', passage: 'Mark 13:32–37', summary: 'Jesus says no one knows the day or hour and compares disciples to servants entrusted with work while their master is away.', details: ['Not the angels nor the Son know the hour; the Father does.', 'Each servant has assigned work.', 'The doorkeeper must watch.', 'The final command to everyone is “Watch!”'], carefulNote: 'The emphasis is ethical readiness—faithful work and watchfulness—not discovering a secret date.' }),
)

MARK_14_LESSON.splice(3, 1,
  scene({ eyebrow: 'Scene 3', title: '“Not what I will, but what You will”', passage: 'Mark 14:32–42', summary: 'In Gethsemane Jesus is deeply distressed, asks Peter, James, and John to watch, and prays three times in obedient trust while they repeatedly sleep.', details: ['Jesus addresses God as “Abba, Father.”', 'He asks that the cup pass, yet submits to the Father’s will.', 'The spirit is willing, but the flesh is weak.', 'At the third return, His betrayer is at hand.'], connections: [{ label: 'Thematic parallel', references: 'Mark 13:33–37', explanation: 'The disciples who were commanded to watch in the discourse now fail to keep watch in the garden.' }] }),
  scene({ eyebrow: 'Scene 4', title: 'Betrayed, arrested, abandoned', passage: 'Mark 14:43–52', summary: 'Judas arrives with an armed crowd and identifies Jesus with a kiss. One bystander cuts the high priest’s servant, but Jesus submits to arrest and all the disciples flee.', details: ['The arresting group comes from the chief priests, scribes, and elders.', 'Jesus points out that He taught daily in the temple without being seized.', 'A young man follows in a linen cloth and escapes naked when seized.', 'Mark leaves the sword-user and young man unnamed.'], carefulNote: 'Teach the confusion and abandonment truthfully without dwelling on injury.' }),
  scene({ eyebrow: 'Scene 5', title: 'Jesus confesses; Peter denies', passage: 'Mark 14:53–72', summary: 'Before the council, Jesus acknowledges that He is the Christ and speaks of the Son of Man. In the courtyard, Peter denies Him three times; the rooster crows twice, and Peter weeps.', details: ['Witnesses disagree about Jesus’ words concerning the temple.', 'The high priest asks directly whether He is the Christ, the Son of the Blessed.', 'The council condemns Him and He is mocked and struck.', 'Peter’s third denial is followed by the second rooster crow.'], carefulNote: 'The council abuse is narratively important but can be described without graphic detail.', connections: [{ label: 'Old Testament background', references: 'Daniel 7:13–14; Psalm 110:1', explanation: 'Jesus joins the Son of Man and right-hand enthronement texts in His answer.' }] }),
)

MARK_15_LESSON.splice(3, 1,
  scene({ eyebrow: 'Scene 3', title: 'Darkness, death, and confession', passage: 'Mark 15:33–41', summary: 'Darkness covers the land from the sixth to ninth hour. Jesus cries the opening of Psalm 22 and dies; the temple veil tears, and a centurion confesses Him as Son of God.', details: ['Jesus’ Aramaic cry is translated for readers.', 'Some misunderstand the cry as a call for Elijah.', 'The veil tears from top to bottom.', 'Women who followed and served Jesus watch from a distance.'], carefulNote: 'Jesus’ cry expresses real anguish and quotes Psalm 22; do not teach that the Father ceased to love the Son.', connections: [{ label: 'Scripture cross-reference', references: 'Psalm 22:1; Mark 1:1, 11', explanation: 'The cry begins Psalm 22, while the centurion’s confession echoes Mark’s opening and baptism.' }] }),
  scene({ eyebrow: 'Scene 4', title: 'Joseph’s tomb; the women watch', passage: 'Mark 15:42–47', summary: 'Joseph of Arimathea courageously asks Pilate for Jesus’ body. After Pilate confirms the death, Joseph wraps the body in linen, lays it in a rock-hewn tomb, and rolls a stone across the entrance.', details: ['Joseph is a prominent council member waiting for God’s kingdom.', 'Pilate is surprised Jesus is already dead and consults the centurion.', 'Mary Magdalene and Mary mother of Joses see where Jesus is laid.', 'Their witness links the burial place to the empty tomb in chapter 16.'], carefulNote: 'The scene is treated reverently and non-graphically.' }),
)

